describe('isValidEmail', () => {
  it('should return true for valid email', () => {
    expect(isValidEmail('user@example.com')).toBe(true);
  });
  it('should return false for email without domain', () => {
    expect(isValidEmail('user@')).toBe(false);
  });
  it('should return false for email without TLD', () => {
    expect(isValidEmail('user@example')).toBe(false);
  });
  it('should return false for email with spaces', () => {
    expect(isValidEmail('user @example.com')).toBe(false);
  });
  it('should return false for empty string', () => {
    expect(isValidEmail('')).toBe(false);
  });
});

describe('sanitizeInput', () => {
  it('should escape less-than symbol', () => {
    expect(sanitizeInput('<script>')).toBe('&lt;script&gt;');
  });
  it('should escape greater-than symbol', () => {
    expect(sanitizeInput('test>')).toContain('&gt;');
  });
  it('should escape double quotes', () => {
    expect(sanitizeInput('test"value')).toContain('&quot;');
  });
  it('should escape single quotes', () => {
    expect(sanitizeInput("test'value")).toContain('&#039;');
  });
  it('should escape multiple dangerous characters', () => {
    expect(sanitizeInput('<img src="x" onerror="alert(1)">')).toBe('&lt;img src=&quot;x&quot; onerror=&quot;alert(1)&quot;&gt;');
  });
  it('should return empty string for empty input', () => {
    expect(sanitizeInput('')).toBe('');
  });
});

describe('createUser', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });
  it('should create user with valid input', async () => {
    const input = { email: 'test@example.com', name: 'John Doe' };
    const user = await createUser(input);
    expect(user).toBeDefined();
    expect(user.email).toBe('test@example.com');
    expect(user.name).toBe('John Doe');
    expect(user.id).toMatch(/^user_/);
  });
  it('should throw error when email is missing', async () => {
    const input = { email: '', name: 'John Doe' };
    await expect(createUser(input)).rejects.toThrow('Email and name are required');
  });
  it('should throw error when name is missing', async () => {
    const input = { email: 'test@example.com', name: '' };
    await expect(createUser(input)).rejects.toThrow('Email and name are required');
  });
  it('should throw error for invalid email format', async () => {
    const input = { email: 'invalid-email', name: 'John Doe' };
    await expect(createUser(input)).rejects.toThrow('Invalid email format');
  });
  it('should sanitize user name', async () => {
    const input = { email: 'test@example.com', name: '<script>alert(1)</script>' };
    const user = await createUser(input);
    expect(user.name).not.toContain('<script>');
  });
  it('should lowercase email address', async () => {
    const input = { email: 'TEST@EXAMPLE.COM', name: 'John Doe' };
    const user = await createUser(input);
    expect(user.email).toBe('test@example.com');
  });
  it('should set createdAt timestamp', async () => {
    const input = { email: 'test@example.com', name: 'John Doe' };
    const user = await createUser(input);
    expect(user.createdAt).toBeInstanceOf(Date);
  });
});

describe('generateId', () => {
  it('should generate ID with user_ prefix', () => {
    const id = generateId();
    expect(id).toMatch(/^user_/);
  });
  it('should generate unique IDs on multiple calls', () => {
    const id1 = generateId();
    const id2 = generateId();
    expect(id1).not.toBe(id2);
  });
  it('should include timestamp in generated ID', () => {
    const id = generateId();
    const parts = id.split('_');
    expect(parts.length).toBe(3);
    expect(/^\d+$/.test(parts[1])).toBe(true);
  });
});

describe('saveUser', () => {
  it('should call database with parameterized query', async () => {
    const mockDb = { query: jest.fn().mockResolvedValue(undefined) };
    const user: User = {
      id: 'user_123',
      email: 'test@example.com',
      name: 'John Doe',
      createdAt: new Date('2024-01-01')
    };
    await saveUser(user);
    // Verify query was called with correct parameters
    expect(mockDb.query).toHaveBeenCalledWith(
      'INSERT INTO users (id, email, name, created_at) VALUES ($1, $2, $3, $4)',
      ['user_123', 'test@example.com', 'John Doe', new Date('2024-01-01')]
    );
  });
});

describe('createUser input validation', () => {
  it('should throw when email is null', async () => {
    const input = { email: null as any, name: 'John' };
    await expect(createUser(input)).rejects.toThrow('Email and name are required');
  });
  it('should throw when name is undefined', async () => {
    const input = { email: 'test@example.com', name: undefined as any };
    await expect(createUser(input)).rejects.toThrow('Email and name are required');
  });
});

describe('isValidEmail edge cases', () => {
  it('should accept single character local part', () => {
    expect(isValidEmail('a@example.com')).toBe(true);
  });
  it('should accept multiple dots in domain', () => {
    expect(isValidEmail('user@sub.example.co.uk')).toBe(true);
  });
  it('should reject multiple @ symbols', () => {
    expect(isValidEmail('user@@example.com')).toBe(false);
  });
  it('should reject email with only @ symbol', () => {
    expect(isValidEmail('@')).toBe(false);
  });
});

describe('sanitizeInput edge cases', () => {
  it('should handle consecutive special characters', () => {
    expect(sanitizeInput('<<<>>>')).toBe('&lt;&lt;&lt;&gt;&gt;&gt;');
  });
  it('should handle mixed quote types', () => {
    const result = sanitizeInput('\'"<>');
    expect(result).toContain('&#039;');
    expect(result).toContain('&quot;');
    expect(result).toContain('&lt;');
    expect(result).toContain('&gt;');
  });
  it('should handle text containing all dangerous characters', () => {
    const input = 'Click <a href="#" onclick=\'alert(1)\'>';
    const result = sanitizeInput(input);
    expect(result).not.toContain('<');
    expect(result).not.toContain('>');
    expect(result).not.toContain('"');
    expect(result).not.toContain("'");
  });
});

