const HTML_ENTITIES: Record<string, string> = {
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#039;'
};

export function sanitizeInput(input: string): string {
  return input.replace(/[<>"']/g, (char) => HTML_ENTITIES[char]);
}
